/* grid.h - the granted surface, and nothing else */
typedef struct grid grid;          /* the implementation stays opaque */
int grid_refresh(grid *g);         /* the only granted call */

/* grid.c - the implementation is reachable only inside this file */
struct grid { int dirty[16]; };
static int recalc(grid *g) { return g->dirty[0]; }   /* internal linkage */
int grid_refresh(grid *g) { return recalc(g); }
